r = await world.call('repo.read_file', path='src/humanize/time.py')
# Find naturalday and naturaldate functions
lines = r['content'].split('\n')
for i, line in enumerate(lines):
    if 'def naturalday' in line or 'def naturaldate' in line:
        print(f"Line {i+1}: {line}")
        # Print context around it
        start = max(0, i-2)
        end = min(len(lines), i+50)
        for j in range(start, end):
            print(f"{j+1:4d}: {lines[j]}")
        print("---")
